/**
 * Cuts docs/METHODOLOGY.md (compiled to HTML by Astro's Markdown pipeline) down to what applies
 * to Heroes of the Storm, so /hots/about/ renders the one source of truth instead of a copy.
 * Pure string work on the compiled HTML: split at <h2>, drop paragraphs that open with another
 * game's name (and everything after them inside that section), keep everything else verbatim.
 * When the document's shape changes, the fallback is to keep content, never to lose it.
 */

export interface DocSection {
  /** Heading id generated by Astro (slug of the heading text). */
  id: string;
  /** Heading text without markup. */
  title: string;
  /** Section HTML including its <h2>. */
  html: string;
}

export interface SplitDoc {
  /** HTML before the first <h2> (title and introduction). */
  intro: string;
  sections: DocSection[];
}

const H2 = /<h2\b[^>]*>/gi;

function stripTags(html: string): string {
  return html
    .replace(/<[^>]+>/g, '')
    .replace(/&amp;/g, '&')
    .replace(/&#x27;|&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .trim();
}

/** Split compiled Markdown into the part before the first <h2> and one block per <h2>. */
export function splitSections(html: string): SplitDoc {
  const starts = [...html.matchAll(H2)].map((m) => m.index);
  if (starts.length === 0) return { intro: html, sections: [] };
  const intro = html.slice(0, starts[0]);
  const sections = starts.map((start, i) => {
    const block = html.slice(start, starts[i + 1] ?? html.length);
    const open = /<h2\b([^>]*)>([\s\S]*?)<\/h2>/i.exec(block);
    const id = open ? (/\bid="([^"]*)"/i.exec(open[1] ?? '')?.[1] ?? '') : '';
    return { id, title: stripTags(open?.[2] ?? ''), html: block };
  });
  return { intro, sections };
}

/** Other games whose paragraphs are cut ("<p><strong>Pokémon Champions</strong> bands on …"). */
const OTHER_GAMES = ['Pokémon', 'Pok&#xE9;mon', 'Pok&eacute;mon', 'MTG', 'Magic'];

/**
 * Remove, inside one section, a paragraph that starts with another game's name in bold and
 * everything after it up to the next bold-led paragraph or <h3>: that run is the other game's
 * subsection (e.g. §8's Pokémon tier bands, its list and its footnote).
 */
export function dropOtherGames(sectionHtml: string): string {
  let html = sectionHtml;
  for (;;) {
    const lead = new RegExp(`<p><strong>(?:${OTHER_GAMES.join('|')})`, 'i').exec(html);
    if (!lead) return html;
    const rest = html.slice(lead.index + 3);
    const next = /<p><strong>|<h3\b/i.exec(rest);
    const end = next ? lead.index + 3 + next.index : html.length;
    html = html.slice(0, lead.index) + html.slice(end);
  }
}

/** METHODOLOGY.md as it applies to HotS: same sections, other games' subsections removed. */
export function hotsMethodology(html: string): SplitDoc {
  const doc = splitSections(html);
  return { intro: doc.intro, sections: doc.sections.map((s) => ({ ...s, html: dropOtherGames(s.html) })) };
}
